(REV, "CHECK", "block", "Reviewer checks each clip against its scene spec field by field: subject, action beats, end state, move, lighting, audio.", "field checklist", "team"),
(REV, "CHECK", "block", "Reviewer checks identity against the character/product sheet using first, middle and last frames.", "3-frame compare", "guide"),
(REV, "CHECK", "major", "Reviewer counts fingers, limbs and subjects at peak-motion frames.", "counts logged", "team"),
(REV, "CHECK", "major", "Reviewer reads every visible glyph; any gibberish fails the clip unless it can be masked.", "text verdict", "guide"),
(REV, "CHECK", "major", "Reviewer verifies lip sync and exact dialogue words.", "dialogue verdict", "guide"),
(REV, "CHECK", "major", "Reviewer listens for hallucinated audio and burned-in subtitles.", "audio verdict", "guide"),
(REV, "CHECK", "major", "Reviewer checks rigid objects and architecture for warping during camera moves.", "geometry verdict", "models"),
(REV, "CHECK", "major", "Reviewer checks the final 1 second for collapse, freeze or morph.", "tail verdict", "team"),
(REV, "CHECK", "major", "Reviewer checks screen direction and eyeline continuity across the scene's cut and into the next scene.", "continuity verdict", "team"),
(REV, "CHECK", "major", "Reviewer verdict is one of PASS, PASS-WITH-TRIM (state cut points), FAIL (state rule IDs). No vague verdicts.", "verdict enum", "team"),
(REV, "CHECK", "major", "Reviewer attaches the rule IDs implicated in every FAIL so the writer can fix the cause, not the symptom.", "rule IDs on FAIL", "team"),
(REV, "CHECK", "block", "Reviewer fails any clip with strobing, sexualized content, realistic minors in sensitive contexts, real-person deception, third-party IP or fake evidence.", "safety verdict", "trust"),
(REV, "CHECK", "major", "Reviewer checks color anchors and style against the lock sheet; drift beyond a light grade fails.", "style verdict", "sora"),
(REV, "CHECK", "major", "Reviewer signs and timestamps the checklist; unsigned clips cannot enter the edit.", "signature", "team"),
(REV, "CHECK", "major", "Reviewer re-checks the stitched scene, not just the individual clips.", "scene-level verdict", "guide"),

# ---------------- cost & approval ----------------
(CST, "RULE", "block", "Video is billed per second. Get explicit approval with the cost stated before generating more than one clip.", "approval logged", "media"),
(CST, "RULE", "major", "One 10-second scene = at least two clips (or one 12s clip). State this when estimating a sequence: a 60s video is at least 12 clips.", "clip count in estimate", "media"),
(CST, "RULE", "major", "Do not promise exact credit totals; state that longer videos cost more and confirm before proceeding.", "no exact credit promises", "media"),
(CST, "RULE", "major", "Draft cheap first: validate keyframes (images) before spending on video.", "keyframes approved before video", "guide"),
